1: import { readFileSync, existsSync } from "node:fs";
2: import { readFile, writeFile, mkdir } from "node:fs/promises";
3: import { join, dirname } from "node:path";
4: import { fileURLToPath } from "node:url";
5: import type { Issue } from "../ralph-loop.js";
6: import { runAgentExecution, type AgentClient } from "../runs/runner.js";
7: import { GitClient, ShellGitClient } from "../utils/git-client.js";
8: import type { PromptArtifactRecorder } from "../loop-run/prompt-artifact-recorder.js";
9: import type {
10:   PromptClientKind,
11:   AgentExecutionUsage,
12:   CriterionVerdict,
13:   CriterionStatus,
14: } from "../loop-run/state.js";
15: 
16: const __filename = fileURLToPath(import.meta.url);
17: const __dirname = dirname(__filename);
