29: export async function loadDevelopmentPrinciples(cwd: string): Promise<string> {
30:   const dirPath = join(cwd, ".github", "ai");
31:   const filePath = join(dirPath, "development-principles.md");
32: 
33:   try {
34:     if (existsSync(filePath)) {
35:       return await readFile(filePath, "utf8");
36:     }
37:     await mkdir(dirPath, { recursive: true });
38:     await writeFile(filePath, BASELINE_PRINCIPLES, "utf8");
39:     return BASELINE_PRINCIPLES;
40:   } catch (err) {
41:     console.warn(`Warning: Could not read or create development principles file: ${(err as Error).message}`);
42:     return "";
43:   }
44: }
45: 
46: const VERDICT_TAG_PATTERN = /<verdict>\s*(PASS|FAIL)\s*<\/verdict>/i;
47: const CRITERION_TAG_PATTERN = /<criterion\b([^>]*)>([\s\S]*?)<\/criterion>/gi;
48: const ATTRIBUTE_PATTERN = /(id|status)\s*=\s*("([^"]*)"|'([^']*)')/gi;
49: const FENCED_BLOCK_PATTERN = /```(?:[\w.-]+)?\n?([\s\S]*?)```/;
50: 
51: export interface ParsedCriterionVerdict extends CriterionVerdict {
52:   ordinal: number;
53:   hasExplicitId: boolean;
54:   stdout: string | null;
55: }
56: 
57: export type VerificationOutcome =
58:   /** Verifier ran and explicitly approved the change. */
59:   | { kind: "verified" }
60:   /** Verifier ran and explicitly rejected the change with feedback. */
61:   | { kind: "rejected"; feedback: string }
62:   /** Verifier ran but produced no parseable verdict tag. Treated like a rejection by orchestration today, but distinguishable for diagnostics. */
63:   | { kind: "inconclusive"; reason: string }
64:   /** Verifier itself failed to execute (CLI error, network, etc). Orchestration currently fails open on this; surface it so it's observable. */
65:   | { kind: "errored"; error: string };
66: 
67: export interface VerificationResult {
68:   /** Typed verifier outcome. Use this to branch deliberately on failure modes. */
69:   outcome: VerificationOutcome;
70:   /**
71:    * Whether orchestration should proceed without another implement attempt.
72:    * Today that means an explicit PASS, and also verifier execution errors,
73:    * which still fail open for loop progress.
74:    */
75:   passed: boolean;
76:   /** When failed, actionable feedback to hand back to the implementer. */
77:   feedback: string;
78:   /** Parsed per-criterion verdict records from the verifier output. */
79:   criteria: ParsedCriterionVerdict[];
80:   raw: string;
81: }
82: 
83: function normalizeCriterionStatus(value: string | undefined): CriterionStatus {
84:   const normalized = value?.trim().toLowerCase();
85:   return normalized === "met" || normalized === "regressed" || normalized === "unmet"
86:     ? normalized
87:     : "unmet";
88: }
89: 
90: function parseCriterionAttributes(rawAttributes: string): { id?: string; status?: string } {
91:   const attributes: { id?: string; status?: string } = {};
92:   for (const match of rawAttributes.matchAll(ATTRIBUTE_PATTERN)) {
93:     const key = match[1]?.toLowerCase();
94:     const value = (match[3] ?? match[4] ?? "").trim();
95:     if (!value) continue;
96:     if (key === "id") attributes.id = value;
97:     if (key === "status") attributes.status = value;
98:   }
99:   return attributes;
100: }
101: 
102: function extractCriterionEvidence(rawEvidence: string): { evidenceProse: string; stdout: string | null } {
103:   const trimmed = rawEvidence.trim();
104:   const stdoutMatch = trimmed.match(FENCED_BLOCK_PATTERN);
105:   if (!stdoutMatch) {
106:     return { evidenceProse: trimmed, stdout: null };
107:   }
108: 
109:   const stdout = stdoutMatch[1] ?? "";
110:   const evidenceProse = trimmed.replace(stdoutMatch[0], "").trim() || "Captured command stdout.";
111:   return { evidenceProse, stdout };
112: }
113: 
114: function parseCriterionVerdicts(raw: string): ParsedCriterionVerdict[] {
115:   const criteria: ParsedCriterionVerdict[] = [];
116:   let ordinal = 0;
117: 
118:   for (const match of raw.matchAll(CRITERION_TAG_PATTERN)) {
119:     ordinal += 1;
120:     const attributes = parseCriterionAttributes(match[1] ?? "");
121:     const { evidenceProse, stdout } = extractCriterionEvidence(match[2] ?? "");
122:     const hasExplicitId = Boolean(attributes.id);
123:     criteria.push({
124:       id: attributes.id ?? `criterion-${ordinal}`,
125:       ordinal,
126:       hasExplicitId,
127:       status: normalizeCriterionStatus(attributes.status),
128:       evidenceProse,
129:       evidenceRef: null,
130:       stdout,
131:     });
132:   }
133: 
134:   return criteria;
135: }
