1: /**
2:  * Persistence adapter for the Loop Run's `RunSnapshot` shape.
3:  *
4:  * The Loop Run owns the domain vocabulary in `../loop-run/state.ts` and
5:  * is the sole authoritative writer; this module turns that snapshot
6:  * into atomic, crash-safe, monotonic-revision JSON writes under
7:  * `.ralph-loop/runs/`. It is intentionally schema-free at the type
8:  * level — every type comes from `../loop-run/state.ts`.
9:  *
10:  * See ADR-0006 and ADR-0007.
11:  */
12: 
13: import { existsSync, mkdirSync, readFileSync, writeFileSync, renameSync, readdirSync, rmSync, statSync } from "node:fs";
14: import { join } from "node:path";
15: 
16: import type {
17:   IssueId,
18:   RunSnapshot,
19:   RunStatus,
20:   TerminalReason,
21:   PanicUndoState,
22:   TaskPhase,
23:   TaskMeta,
24:   ReviewPhase,
25:   SchedulerProgress,
26:   TaskRecord,
27: } from "../loop-run/state.js";
28: import { normalizeSteeringPostCrash } from "../loop-run/state.js";
29: import { buildUsageSummary } from "../loop-run/usage.js";
30: 
31: const RUNS_DIR = ".ralph-loop/runs";
32: const PROMPTS_DIR = ".ralph-loop/prompts";
33: const CRITERION_EVIDENCE_DIR = ".ralph-loop/criterion-evidence";
34: const HANDOFF_DIR = ".ralph-loop/handoffs";
35: const ACTIVE_FILE = "active.json";
36: const ARCHIVE_DIR = "archived";
37: 
38: function normalizeTaskRecord(task: TaskRecord): TaskRecord {
39:   return {
40:     ...task,
41:     criteria: Array.isArray(task.criteria) ? task.criteria : [],
42:     criterionIdentities: Array.isArray(task.criterionIdentities) ? task.criterionIdentities : [],
43:     liveSteering: Array.isArray(task.liveSteering) ? task.liveSteering : [],
44:   };
45: }
46: 
47: function normalizeRunSnapshot(state: RunSnapshot): RunSnapshot {
48:   return {
49:     ...state,
50:     tasks: Object.fromEntries(
51:       Object.entries(state.tasks ?? {}).map(([key, task]) => [key, normalizeTaskRecord(task)]),
52:     ),
53:   };
54: }
55: 
56: export class LoopRunTracker {
57:   private readonly runsDir: string;
58:   private readonly activeFilePath: string;
59:   private readonly archiveDir: string;
60: 
61:   constructor(private readonly cwd: string) {
62:     this.runsDir = join(cwd, RUNS_DIR);
63:     this.activeFilePath = join(this.runsDir, ACTIVE_FILE);
64:     this.archiveDir = join(this.runsDir, ARCHIVE_DIR);
65:   }
66: 
67:   create(params: {
68:     runId: string;
69:     repoCwd: string;
70:     startCommit: string;
71:     scheduler: {
72:       maxIterations: number;
73:       maxParallel: number;
74:       skippedIds: IssueId[];
75:     };
76:     rollbackSnapshotId?: string;
77:     capturePromptTranscripts?: boolean;
78:   }): RunSnapshot {
79:     const promptTranscripts =
80:       params.capturePromptTranscripts === false
81:         ? { enabled: false as const }
82:         : { enabled: true as const };
83: 
84:     const state: RunSnapshot = {
85:       runId: params.runId,
86:       revision: 1,
87:       repoCwd: params.repoCwd,
88:       startCommit: params.startCommit,
89:       status: "running",
90:       owner: {
91:         pid: process.pid,
92:         heartbeatAt: new Date().toISOString(),
93:       },
94:       scheduler: {
95:         maxIterations: params.scheduler.maxIterations,
96:         iterationsStarted: 0,
97:         maxParallel: params.scheduler.maxParallel,
98:         skippedIds: params.scheduler.skippedIds,
99:       },
100:       tasks: {},
101:       review: { phase: "pending" },
102:       rollbackSnapshotId: params.rollbackSnapshotId,
103:       promptTranscripts,
104:       usageLedger: [],
105:       usageSummary: buildUsageSummary([]),
106:     };
107: 
108:     this.atomicWrite(state);
109:     return state;
110:   }
111: 
112:   read(): RunSnapshot | null {
113:     this.cleanupTempFile();
114:     if (!existsSync(this.activeFilePath)) return null;
115:     const raw = readFileSync(this.activeFilePath, "utf8");
116:     return normalizeRunSnapshot(JSON.parse(raw) as RunSnapshot);
117:   }
118: 
119:   private cleanupTempFile(): void {
120:     const tmpPath = this.activeFilePath + ".tmp";
121:     if (existsSync(tmpPath) && !existsSync(this.activeFilePath)) {
122:       renameSync(tmpPath, this.activeFilePath);
123:     }
124:   }
125: 
126:   /**
127:    * Escape-hatch reducer-style update for callers that need to mutate
128:    * multiple snapshot fields atomically (e.g. stale-run recovery
129:    * restart surgery). Normal phase / meta / scheduler / review writes
130:    * should go through the targeted methods below.
131:    */
132:   update(updater: (state: RunSnapshot) => RunSnapshot): RunSnapshot {
133:     const current = this.read();
134:     if (!current) {
135:       throw new Error("Cannot update: no active tracker state found");
136:     }
137:     const next = updater(current);
138:     next.revision = current.revision + 1;
139:     this.atomicWrite(next);
140:     return next;
141:   }
142: 
143:   updateHeartbeat(): RunSnapshot {
144:     return this.update((s) => ({
145:       ...s,
146:       owner: { ...s.owner, heartbeatAt: new Date().toISOString() },
147:     }));
148:   }
149: 
150:   adoptOwnership(): RunSnapshot {
151:     return this.update((s) => ({
152:       ...s,
153:       status: "running",
154:       owner: {
155:         pid: process.pid,
156:         heartbeatAt: new Date().toISOString(),
157:       },
158:     }));
159:   }
160: 
161:   isOwnerAlive(): boolean {
162:     const state = this.read();
163:     if (!state) return false;
164:     try {
165:       process.kill(state.owner.pid, 0);
166:       return true;
167:     } catch {
168:       return false;
169:     }
170:   }
171: 
172:   isStale(maxAgeMs: number = 30_000): boolean {
173:     const state = this.read();
174:     if (!state) return true;
175:     if (!this.isOwnerAlive()) return true;
176:     const heartbeatTime = new Date(state.owner.heartbeatAt).getTime();
177:     return Date.now() - heartbeatTime > maxAgeMs;
178:   }
179: 
180:   markCompletedAndArchive(): RunSnapshot | null {
181:     return this.markStatusAndArchive("completed", undefined);
182:   }
183: 
184:   markStatus(status: RunStatus): RunSnapshot | null {
185:     const state = this.read();
186:     if (!state) return null;
187:     return this.update((current) => ({
188:       ...current,
189:       status,
190:     }));
191:   }
192: 
193:   recordReviewPhase(phase: ReviewPhase): void {
194:     this.update((s) => ({
195:       ...s,
196:       review: { phase },
197:     }));
198:   }
199: 
200:   recordPanicUndo(partial: Partial<PanicUndoState>): void {
201:     this.update((s) => ({
202:       ...s,
203:       panicUndo: { ...(s.panicUndo ?? { phase: "requested" }), ...partial },
204:     }));
205:   }
206: 
207:   markStatusAndArchive(status: RunStatus, terminalReason?: TerminalReason): RunSnapshot | null {
208:     const state = this.read();
209:     if (!state) return null;
210: 
211:     const completed: RunSnapshot = {
212:       ...state,
213:       status,
214:       ...(terminalReason ? { terminalReason } : {}),
215:     };
216: 
217:     this.atomicWrite(completed);
218: 
219:     if (!existsSync(this.archiveDir)) {
220:       mkdirSync(this.archiveDir, { recursive: true });
221:     }
222: 
223:     const archiveName = `completed-${Date.now()}-${state.runId}.json`;
224:     const archivePath = join(this.archiveDir, archiveName);
225: 
226:     renameSync(this.activeFilePath, archivePath);
227: 
228:     this.pruneArchive();
229: 
230:     return completed;
231:   }
232: 
233:   private pruneArchive(): void {
234:     if (!existsSync(this.archiveDir)) return;
235: 
236:     const files = readdirSync(this.archiveDir, { withFileTypes: true })
237:       .filter((f) => f.isFile() && f.name.endsWith(".json"))
238:       .map((f) => ({
239:         name: f.name,
240:         mtime: statSync(join(this.archiveDir, f.name)).mtimeMs,
241:       }))
242:       .sort((a, b) => b.mtime - a.mtime);
243: 
244:     const toRemove = files.slice(10);
245:     const promptsDir = join(this.cwd, PROMPTS_DIR);
246:     const criterionEvidenceDir = join(this.cwd, CRITERION_EVIDENCE_DIR);
247: 
248:     for (const file of toRemove) {
249:       // Read the archived file to extract runId before deleting
250:       try {
251:         const raw = readFileSync(join(this.archiveDir, file.name), "utf8");
252:         const state = JSON.parse(raw) as RunSnapshot;
253:         const runPromptsDir = join(promptsDir, state.runId);
254:         if (existsSync(runPromptsDir)) {
255:           rmSync(runPromptsDir, { recursive: true, force: true });
256:         }
257:         const runCriterionEvidenceDir = join(criterionEvidenceDir, state.runId);
258:         if (existsSync(runCriterionEvidenceDir)) {
259:           rmSync(runCriterionEvidenceDir, { recursive: true, force: true });
260:         }
261:         const handoffDir = join(this.cwd, HANDOFF_DIR);
262:         const runHandoffDir = join(handoffDir, state.runId);
263:         if (existsSync(runHandoffDir)) {
264:           rmSync(runHandoffDir, { recursive: true, force: true });
265:         }
266:       } catch {
267:         // File may be malformed; skip artifact cleanup for this entry
268:       }
269: 
270:       rmSync(join(this.archiveDir, file.name), { force: true });
271:     }
272:   }
273: 
274:   private ensureDirs(): void {
275:     if (!existsSync(this.runsDir)) {
276:       mkdirSync(this.runsDir, { recursive: true });
277:     }
278:   }
