371:   private atomicWrite(state: RunSnapshot): void {
372:     this.ensureDirs();
373:     const tmpPath = this.activeFilePath + ".tmp";
374:     writeFileSync(tmpPath, JSON.stringify(state, null, 2), "utf8");
375: 
376:     try {
377:       renameSync(tmpPath, this.activeFilePath);
378:     } catch (error) {
379:       if (!isWindowsRenameCollision(error)) {
380:         throw error;
381:       }
382:       rmSync(this.activeFilePath, { force: true });
383:       renameSync(tmpPath, this.activeFilePath);
384:     }
385:   }
