44: export interface LoopRunOptions {
45:   /**
46:    * Authoritative durable tracker for this run. The Loop Run becomes its
47:    * sole writer for the duration of the run; callers must not call
48:    * `recordPhase`, `recordMeta`, `recordSchedulerProgress`,
49:    * `recordReviewPhase`, or archive methods on the tracker directly while
50:    * a Loop Run is active.
51:    */
52:   tracker: LoopRunTracker;
53: 
54:   /**
55:    * Whether to capture prompt transcripts for this run. When enabled,
56:    * the run's promptTranscripts state defaults to `{ enabled: true }`.
57:    * When explicitly false, persists `{ enabled: false }` in the tracker.
58:    * Defaults to true.
59:    */
60:   capturePromptTranscripts?: boolean;
61: }
62: 
63: export class LoopRun {
64:   private readonly tracker: LoopRunTracker;
65:   private readonly subscribers: LoopRunSubscriber[] = [];
66:   private readonly capturePromptTranscripts: boolean;
67:   private finished = false;
68:   private lastDrainKilledCount = 0;
69: 
70:   constructor(options: LoopRunOptions) {
71:     this.tracker = options.tracker;
72:     this.capturePromptTranscripts = options.capturePromptTranscripts ?? true;
73:   }
74: 
75:   /**
76:    * Register a subscriber that receives every fact event emitted by this
77:    * Loop Run. Subscribers are invoked synchronously in registration order
78:    * after the underlying durable write returns.
79:    *
80:    * Subscribers must be side-effect-light; long-running work blocks the
81:    * coordinator and stalls the loop.
82:    *
83:    * @returns an unsubscribe function.
84:    */
85:   /**
86:    * Return the current durable snapshot, or `null` if no run has been
87:    * persisted yet (or it has been archived). Query-only; this never
88:    * writes and never emits events. Use this whenever a consumer needs
89:    * to inspect the authoritative run state without going behind the
90:    * Loop Run's back to the tracker.
91:    */
92:   snapshot(): RunSnapshot | null {
93:     return this.tracker.read();
94:   }
95: 
96:   subscribe(subscriber: LoopRunSubscriber): () => void {
97:     this.subscribers.push(subscriber);
98:     return () => {
99:       const idx = this.subscribers.indexOf(subscriber);
100:       if (idx >= 0) this.subscribers.splice(idx, 1);
101:     };
102:   }
103: 
104:   /**
105:    * Bootstrap the Loop Run's durable state and rollback snapshot.
106:    *
107:    * Combines tracker create-or-adopt with snapshot init-or-adopt into a
108:    * single atomic-looking sequence so that the snapshot id is always
109:    * persisted into the tracker by the Loop Run (the sole writer), never
110:    * by the caller. Emits either `snapshotAdopted` or `snapshotCaptured`
111:    * depending on whether an existing tracker with a snapshot id is
112:    * resumed or a fresh snapshot is captured.
113:    *
114:    * Returns the resulting tracker state so callers can read scheduler
115:    * progress, tasks, etc.
116:    */
117:   startOrResume(params: {
118:     workspaceManager: WorkspaceManager;
119:     runIdFactory: () => string;
120:     repoCwd: string;
121:     startCommit: string;
122:     scheduler: { maxIterations: number; maxParallel: number; skippedIds: IssueId[] };
123:     rollbackSnapshot?: { isNewBranch?: boolean; createdBranch?: string; originalBranch?: string };
124:   }): RunSnapshot {
125:     this.assertActive();
126:     const existing = this.tracker.read();
127: 
128:     if (existing?.rollbackSnapshotId) {
129:       params.workspaceManager.adoptSnapshot(existing.rollbackSnapshotId);
130:       this.emit({ kind: "snapshotAdopted", snapshotId: existing.rollbackSnapshotId });
131:       return existing;
132:     }
133: 
134:     const snapshot = params.workspaceManager.initializeWorkspaceLock(params.rollbackSnapshot);
135:     let state: RunSnapshot;
136:     if (existing) {
137:       state = this.tracker.update((s) => ({
138:         ...s,
139:         rollbackSnapshotId: snapshot.snapshotDirectory,
140:       }));
141:     } else {
142:       state = this.tracker.create({
143:         runId: params.runIdFactory(),
144:         repoCwd: params.repoCwd,
145:         startCommit: params.startCommit,
146:         scheduler: params.scheduler,
147:         rollbackSnapshotId: snapshot.snapshotDirectory,
148:         capturePromptTranscripts: this.capturePromptTranscripts,
149:       });
150:     }
151:     this.emit({ kind: "snapshotCaptured", snapshotId: snapshot.snapshotDirectory });
152:     return state;
153:   }
154: 
155:   /**
156:    * Run the rollback (write-then-emit). Delegates to the Rollback
157:    * Service; emits `snapshotRolledBack` with the success flag after the
158:    * service returns.
159:    */
160:   async rollback(workspaceManager: WorkspaceManager): Promise<RollbackResult> {
161:     this.assertActive();
162:     const resetTarget = workspaceManager.getSnapshot()?.head ?? "";
163:     const result = await workspaceManager.rollback();
164:     // Guard against a missing tracker — cleanupUntracked inside
165:     // rollbackService may have removed active.json before we can write.
166:     try {
167:       if (result.success) {
168:         this.tracker.recordPanicUndo({
169:           phase: "rollback-completed",
170:           rollbackCompletedAt: new Date().toISOString(),
171:           snapshotRetained: result.snapshotRetained,
172:           snapshotPath: result.snapshotPath,
173:           affectedPaths: result.affectedPaths,
174:         });
175:       } else {
176:         this.tracker.recordPanicUndo({
177:           phase: "rollback-failed",
178:           rollbackFailedAt: new Date().toISOString(),
179:           snapshotRetained: result.snapshotRetained,
180:           snapshotPath: result.snapshotPath,
181:           affectedPaths: result.affectedPaths,
182:         });
183:       }
184:     } catch {
185:       // Tracker state gone — diagnostic write is best-effort.
186:     }
187:     this.emit({
188:       kind: "snapshotRolledBack",
189:       success: result.success,
190:       killedCount: this.lastDrainKilledCount,
191:       resetTarget,
192:       snapshotRetained: result.snapshotRetained,
193:       snapshotPath: result.snapshotPath,
194:       affectedPaths: result.affectedPaths,
195:     });
196:     return result;
197:   }
198: 
199:   /**
200:    * Drive the panic-undo drain. Announces `panicUndoRequested` before
201:    * attempting to terminate any live agent processes, then waits up to
202:    * `timeoutMs` for them to exit. On a successful drain emits
203:    * `processesDrained { killedCount }` so subscribers can report the
204:    * outcome; on timeout no drain fact is emitted and the caller is
205:    * expected to abort the undo to avoid live-writer conflicts during
206:    * the subsequent rollback.
207:    *
208:    * This does **not** itself perform the rollback — callers must follow
209:    * a successful drain with {@link rollback}. Keeping the two joints
210:    * separate matches the operational sequence (`panicUndoRequested →
211:    * processesDrained → snapshotRolledBack`) and lets a reporter render
212:    * each step independently.
213:    */
214:   async requestPanicUndo(
215:     processRegistry: { size: number; killAndWait: (timeoutMs?: number) => Promise<boolean> },
216:     timeoutMs: number,
217:   ): Promise<{ allExited: boolean; killedCount: number }> {
218:     this.assertActive();
219:     const killedCount = processRegistry.size;
220:     // Guard against a missing tracker — diagnostic writes are best-effort.
221:     try {
222:       this.tracker.recordPanicUndo({
223:         phase: "requested",
224:         requestedAt: new Date().toISOString(),
225:         killedCount,
226:         timeoutMs,
227:       });
228:     } catch {
229:       // Tracker state gone — proceed with drain regardless.
230:     }
231:     this.emit({ kind: "panicUndoRequested" });
232:     const allExited = await processRegistry.killAndWait(timeoutMs);
233:     if (allExited) {
234:       this.lastDrainKilledCount = killedCount;
235:       try {
236:         this.tracker.recordPanicUndo({
237:           phase: "processes-drained",
238:           processesDrainedAt: new Date().toISOString(),
239:         });
240:       } catch {
241:         // Tracker state gone — diagnostic write is best-effort.
242:       }
243:       this.emit({ kind: "processesDrained", killedCount });
244:     } else {
245:       try {
246:         this.tracker.recordPanicUndo({
247:           phase: "drain-aborted",
248:         });
249:       } catch {
250:         // Tracker state gone — diagnostic write is best-effort.
251:       }
252:       this.emit({
253:         kind: "panicUndoAborted",
254:         reason: "timeout",
255:         activeProcesses: killedCount,
256:         timeoutMs,
257:       });
258:     }
259:     return { allExited, killedCount };
260:   }
