262:   /**
263:    * Clean up the rollback snapshot at end-of-run. Emits `snapshotArchived`
264:    * after cleanup returns (regardless of whether the snapshot was
265:    * retained on disk for manual recovery).
266:    */
267:   cleanupSnapshot(
268:     workspaceManager: WorkspaceManager,
269:     options: { retainSnapshot: boolean },
270:   ): void {
271:     workspaceManager.releaseWorkspaceLock(options);
272:     this.emit({ kind: "snapshotArchived" });
273:   }
