275:   /**
276:    * Record a task phase transition (write-then-emit).
277:    *
278:    * The internal tracker write happens first; the `taskPhaseChanged` fact
279:    * is emitted only after that write returns successfully. If the write
280:    * throws, no event is emitted.
281:    */
282:   recordTaskPhase(
283:     issueId: IssueId,
284:     phase: TaskPhase,
285:     meta?: TaskMeta,
286:   ): void {
287:     this.assertActive();
288:     const before = this.readTaskPhase(issueId);
289:     if (meta) {
290:       this.tracker.update((state) => this.applyMeta(state, issueId, meta));
291:     }
292:     this.tracker.update((state) => this.applyPhase(state, issueId, phase));
293:     this.emit({
294:       kind: "taskPhaseChanged",
295:       issueId,
296:       from: before,
297:       to: phase,
298:       meta,
299:     });
300:   }
