302:   /**
303:    * Record task metadata without a phase change (write-then-emit).
304:    * Used for mid-phase updates such as `attempt`, `lastError`,
305:    * `preMergeHead`, `integratedHead`.
306:    */
307:   recordTaskMeta(issueId: IssueId, meta: TaskMeta): void {
308:     this.assertActive();
309:     this.tracker.update((state) => this.applyMeta(state, issueId, meta));
310:     this.emit({ kind: "taskMetaChanged", issueId, meta });
311:   }
