323:     this.assertActive();
324:     if (!criteria || criteria.length === 0) return;
325: 
326:     const current = this.tracker.read();
327:     if (!current) {
328:       throw new Error("Cannot record criterion verdicts: no active tracker state found");
329:     }
330: 
331:     const key = String(issueId);
332:     const existingTask = current.tasks[key] ?? {
333:       issueId,
334:       title: "",
335:       body: "",
336:       phase: "scheduled" as TaskPhase,
337:       attempt: 0,
338:       criteria: [],
339:       criterionIdentities: [],
340:     };
341:     const identities = [...(existingTask.criterionIdentities ?? [])];
342: 
343:     const persistedCriteria = criteria.map((criterion, index) => {
344:       const ordinal = criterion.ordinal ?? index + 1;
345:       const stableId = this.resolveCriterionIdentity(criterion, ordinal, identities);
346:       const stdout = criterion.stdout?.length ? criterion.stdout : null;
347:       const evidenceRef = stdout
348:         ? this.writeCriterionEvidenceArtifact(current.repoCwd, current.runId, issueId, stableId, stdout)
