350:       return {
351:         id: stableId,
352:         status: this.normalizeCriterionStatus(criterion.status),
353:         evidenceProse: criterion.evidenceProse.trim() || (stdout ? "Captured command stdout." : ""),
354:         evidenceRef,
355:       } satisfies CriterionVerdict;
356:     });
357: 
358:     this.tracker.update((state) => ({
359:       ...state,
360:       tasks: {
361:         ...state.tasks,
362:         [key]: {
363:           ...(state.tasks[key] ?? existingTask),
364:           criteria: persistedCriteria,
365:           criterionIdentities: identities,
366:         },
367:       },
368:     }));
369:   }
