639:   private writeCriterionEvidenceArtifact(
640:     repoCwd: string,
641:     runId: string,
642:     issueId: IssueId,
643:     criterionId: string,
644:     stdout: string,
645:   ): string {
646:     const criterionDir = join(
647:       repoCwd,
648:       CRITERION_EVIDENCE_DIR,
649:       this.sanitizePathSegment(runId),
650:       `issue-${this.sanitizePathSegment(String(issueId))}`,
651:       this.sanitizePathSegment(criterionId),
652:     );
653:     if (!existsSync(criterionDir)) {
654:       mkdirSync(criterionDir, { recursive: true });
655:     }
656: 
657:     const hash = createHash("sha256").update(stdout).digest("hex").slice(0, 12);
658:     const relativePath = join(
659:       CRITERION_EVIDENCE_DIR,
660:       this.sanitizePathSegment(runId),
661:       `issue-${this.sanitizePathSegment(String(issueId))}`,
662:       this.sanitizePathSegment(criterionId),
663:       `${hash}.txt`,
664:     );
665:     const absolutePath = join(repoCwd, relativePath);
666:     if (!existsSync(absolutePath)) {
667:       const tmpPath = absolutePath + ".tmp";
668:       writeFileSync(tmpPath, stdout, "utf8");
669:       renameSync(tmpPath, absolutePath);
670:     }
671:     return relativePath;
672:   }
