229:   if (issueId === undefined) {
230:     return { runStreamingUsage: usage };
231:   }
232:   const key = workerKey(issueId);
233:   const workers = new Map(state.workers);
234:   const existing = workers.get(key);
235:   if (!existing) return null;
236:   const currentPhase = existing.phase;
237:   const phaseRecord = existing.phases.get(currentPhase) ?? { contextTokens: null, maxContext: null };
238:   const updatedPhases = new Map(existing.phases);
239:   updatedPhases.set(currentPhase, {
240:     contextTokens: usage.contextTokens ?? phaseRecord.contextTokens,
241:     maxContext: usage.maxContext ?? phaseRecord.maxContext,
242:   });
243:   workers.set(key, {
244:     ...existing,
245:     phases: updatedPhases,
246:     streamingUsage: usage,
247:     latestInputTokens: usage.inputTokens,
248:     latestContextTokens: usage.contextTokens ?? existing.latestContextTokens,
249:   });
250:   return { workers };
251: }
