202: export function appendRunLogEntryToInkState(
203:   state: InkRunViewState,
204:   entry: RunLogEntry,
205:   at: string,
206: ): InkRunViewState {
207:   const sourceKey = entry.kind === "issue-text" ? `issue:${String(entry.issueId)}` : "run";
208:   const issueId = entry.kind === "issue-text" ? entry.issueId : undefined;
209:   let nextState = state;
210:   let remaining = entry.text;
211: 
212:   while (remaining.length > 0) {
213:     const newlineIndex = remaining.indexOf("\n");
214:     if (newlineIndex === -1) {
215:       const phase = getWorkerPhase(nextState, issueId);
216:       const partial = appendLogFragment(nextState, sourceKey, issueId, phase, remaining, false, at);
217:       const touched = touchWorkerLatestAt(nextState, issueId, at);
218:       nextState = { ...nextState, ...partial, ...(touched ?? {}) };
219:       break;
220:     }
221: 
222:     const line = remaining.slice(0, newlineIndex);
223:     const phase = getWorkerPhase(nextState, issueId);
224:     const closed = appendLogFragment(nextState, sourceKey, issueId, phase, line, true, at);
225:     const touched = touchWorkerLatestAt(nextState, issueId, at);
226:     nextState = { ...nextState, ...closed, ...(touched ?? {}) };
227:     remaining = remaining.slice(newlineIndex + 1);
228: 
229:     if (remaining.length === 0 && entry.text.endsWith("\n")) {
230:       break;
231:     }
232:   }
233: 
234:   return nextState;
235: }
