237: export function formatTokenCount(value: number): string {
238:   if (value >= 1_000_000) {
239:     const millions = (value / 1_000_000).toFixed(1);
240:     return `${millions.endsWith(".0") ? millions.slice(0, -2) : millions}M`;
241:   }
242:   if (value >= 1_000) {
243:     return `${Math.round(value / 1_000)}K`;
244:   }
245:   return String(value);
246: }
