248: export function formatContextWindowFill(
249:   state: InkRunViewState,
250:   worker: WorkerDashboardRow,
251: ): string {
252:   if (worker.latestContextTokens === null) {
253:     return "unknown";
254:   }
255:   if (state.maxContext === null) {
256:     return `unknown (${formatTokenCount(worker.latestContextTokens)})`;
257:   }
258:   const percent = Math.round((worker.latestContextTokens / state.maxContext) * 100);
259:   return `${percent}% (${formatTokenCount(worker.latestContextTokens)}/${formatTokenCount(state.maxContext)})`;
260: }
